            let value: Swift.String = try deserializer.readString(memberSchema)
            self.registryId = value
        case 2:
            let value: Swift.String = try deserializer.readString(memberSchema)
            self.repositoryName = value
        case 3:
            let value: Swift.String = try deserializer.readString(memberSchema)
            self.uploadId = value
        default: break
        }
    }
}
